    [Fact]
    public async Task ChatStreamSendsStreamTrueAndDecodesEvents()
    {
        var handler = new StubHandler().Sse(": hello\n\nevent: ping\ndata:\n\n" + TextEvent + DoneEvent, ("X-Dialog-Id", "d9"), ("X-Turn-No", "4"));
        using var client = Sdk.Client(handler);
        await using var stream = client.Chat.CreateStreamAsync(new ChatMessageRequest { Message = "hi" });
        Assert.Null(stream.Response);
        Assert.Empty(handler.Requests);

        var events = new List<ChatEvent>();
        await foreach (var chatEvent in stream)
        {
            events.Add(chatEvent);
        }

        Assert.Equal(new[] { "text", "done" }, events.Select(chatEvent => chatEvent.Type));
        Assert.Equal("Hello", events[0].AsText?.Delta);
        Assert.Equal("end_turn", events[1].AsDone?.StopReason);
        Assert.Equal("d9", stream.Response?.GetHeader("X-Dialog-Id"));

        var request = Assert.Single(handler.Requests);
        Assert.Equal("text/event-stream", request.Header("Accept"));
        Assert.False(string.IsNullOrEmpty(request.Header("Idempotency-Key")));
