    [Fact]
    public async Task RealTimeoutCancellationAndRefusedConnection()
    {
        await using var server = new LoopbackServer(connection => connection.WaitForCloseAsync(TimeSpan.FromSeconds(20)));
        using var client = new TungoClient(new TungoClientOptions
        {
            ApiKey = Sdk.ApiKey,
            CompanyId = "co_1",
            BaseUrl = server.BaseUrl,
            Timeout = TimeSpan.FromMilliseconds(300),
            MaxRetries = 0,
        });
        await Assert.ThrowsAsync<TungoTimeoutException>(() => client.Companies.GetAsync());

        using var cancellation = new CancellationTokenSource(TimeSpan.FromMilliseconds(100));
        var cancelled = await Assert.ThrowsAnyAsync<OperationCanceledException>(
            () => client.Companies.GetAsync(new RequestOptions { Timeout = TimeSpan.FromSeconds(30) }, cancellation.Token));
        Assert.IsNotAssignableFrom<TungoException>(cancelled);

        // A port nobody listens on.
        var listener = new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback, 0);
        listener.Start();
        var port = ((System.Net.IPEndPoint)listener.LocalEndpoint).Port;
        listener.Stop();
        using var nowhere = new TungoClient(new TungoClientOptions
        {
            ApiKey = Sdk.ApiKey,
            CompanyId = "co_1",
            BaseUrl = new Uri("http://127.0.0.1:" + port),
            MaxRetries = 0,
        });
        var refused = await Assert.ThrowsAsync<TungoConnectionException>(() => nowhere.Companies.GetAsync());
        Assert.NotNull(refused.InnerException);
    }

    [Fact]
    public async Task ARedirectIsNeverFollowedAndTheKeyStaysHome()
    {
        await using var other = new LoopbackServer(connection => connection.WriteAsync("HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\n\r\n{}"));
        var location = new Uri(other.BaseUrl, "/v1/elsewhere").AbsoluteUri;
        await using var server = new LoopbackServer(connection => connection.WriteAsync("HTTP/1.1 302 Found\r\nLocation: " + location + "\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"));
        using var client = new TungoClient(new TungoClientOptions { ApiKey = Sdk.ApiKey, CompanyId = "co_1", BaseUrl = server.BaseUrl, MaxRetries = 0 });

        var plain = await Assert.ThrowsAnyAsync<TungoApiException>(() => client.Companies.GetAsync());
        Assert.Equal(302, plain.StatusCode);
        var streamed = await Assert.ThrowsAnyAsync<TungoApiException>(async () =>
        {
            await foreach (var chatEvent in client.Chat.CreateStreamAsync(new ChatMessageRequest { Message = "hi" }))
            {
                Assert.Fail("a redirect does not open a stream: " + chatEvent);
            }
        });
        Assert.Equal(302, streamed.StatusCode);
        Assert.Equal(2, server.Connections);
        Assert.Equal(0, other.Connections);

        // A handler of the caller that follows redirects is refused.
        using var following = new HttpClientHandler();
        Assert.Throws<TungoConfigurationException>(() => new TungoClient(new TungoClientOptions { ApiKey = Sdk.ApiKey, HttpMessageHandler = following }));
    }

    [Fact]
    public async Task ACallersHttpClientThatFollowsARedirectDoesNotDeliverTheForeignResponse()
    {
        await using var other = new LoopbackServer(connection => connection.WriteAsync("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: " + Encoding.UTF8.GetByteCount(Sdk.CompanyJson).ToString(System.Globalization.CultureInfo.InvariantCulture) + "\r\nConnection: close\r\n\r\n" + Sdk.CompanyJson));
        var location = new Uri(other.BaseUrl, "/v1/elsewhere").AbsoluteUri;
        await using var server = new LoopbackServer(connection => connection.WriteAsync("HTTP/1.1 307 Temporary Redirect\r\nLocation: " + location + "\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"));

        // An HttpClient with the platform defaults follows redirects; the SDK cannot see or change its handler.
        using var http = new HttpClient { Timeout = Timeout.InfiniteTimeSpan };
        using var client = new TungoClient(new TungoClientOptions { ApiKey = Sdk.ApiKey, CompanyId = "co_1", BaseUrl = server.BaseUrl, MaxRetries = 0, HttpClient = http });
        var error = await Assert.ThrowsAsync<TungoConfigurationException>(() => client.Companies.GetAsync());
        Assert.Contains("followed a redirect", error.Message, StringComparison.Ordinal);
        Assert.Contains(other.BaseUrl.GetLeftPart(UriPartial.Authority), error.Message, StringComparison.Ordinal);
        Assert.Equal(1, server.Connections);
    }

